import { EventEmitter } from '../mochievents/index.js';
import { loadNative } from '../mochinode/index.js';

const wsNative = await loadNative('mochiws.dll');

function httpGet(url) {
    const raw = String(wsNative.httpGet(String(url)));
    const statusKey = '"status":';
    const statusAt = raw.indexOf(statusKey);
    const status = statusAt >= 0 ? Number(raw.slice(statusAt + statusKey.length, raw.indexOf(',', statusAt))) : 0;
    const bodyKey = '"bodyHex":"';
    const bodyAt = raw.indexOf(bodyKey);
    const bodyEnd = bodyAt >= 0 ? raw.indexOf('"', bodyAt + bodyKey.length) : -1;
    return { status, ok: raw.indexOf('"ok":true') >= 0, headers: {}, bodyHex: bodyEnd > bodyAt ? raw.slice(bodyAt + bodyKey.length, bodyEnd) : '' };
}

function httpRequest(method, url, body, contentType) {
    const raw = String(wsNative.httpRequest(String(method).toUpperCase(), String(url),
                                            body == null ? undefined : String(body),
                                            contentType == null ? undefined : String(contentType)));
    const statusKey = '"status":';
    const statusAt = raw.indexOf(statusKey);
    const status = statusAt >= 0 ? Number(raw.slice(statusAt + statusKey.length, raw.indexOf(',', statusAt))) : 0;
    const bodyKey = '"bodyHex":"';
    const bodyAt = raw.indexOf(bodyKey);
    const bodyEnd = bodyAt >= 0 ? raw.indexOf('"', bodyAt + bodyKey.length) : -1;
    return { status, ok: raw.indexOf('"ok":true') >= 0, headers: {}, bodyHex: bodyEnd > bodyAt ? raw.slice(bodyAt + bodyKey.length, bodyEnd) : '' };
}

function unsupported(name) {
    const err = new Error(`mochihttp: ${name} is unavailable on MochiBerry runtime`);
    err.code = 'MOCHI_UNSUPPORTED';
    return err;
}

function bytesFromHex(hex) {
    const s = String(hex || '').replace(/[^0-9a-fA-F]/g, '');
    const out = new Uint8Array(Math.floor(s.length / 2));
    for (let i = 0; i < out.length; i++) out[i] = parseInt(s.slice(i * 2, i * 2 + 2), 16) || 0;
    return out;
}

export class IncomingMessage extends EventEmitter {
    constructor(status = 500, headers = {}, body = new Uint8Array(0)) {
        super();
        this.statusCode = status;
        this.statusMessage = String(headers.statusMessage || '');
        this.headers = headers || {};
        this._body = body;
        this._offset = 0;
        this.destroyed = false;
    }

    read() {
        if (this.destroyed || this._offset >= this._body.length) return null;
        const out = this._body.subarray(this._offset);
        this._offset = this._body.length;
        return out;
    }

    destroy(error) {
        if (error) this.emit('error', error);
        this.destroyed = true;
        this.emit('close');
    }

    async *[Symbol.asyncIterator]() {
        while (!this.destroyed && this._offset < this._body.length) {
            const chunk = this.read();
            if (!chunk) break;
            this.emit('data', chunk);
            yield chunk;
        }
        if (!this.destroyed) this.emit('end');
    }
}

export class ClientRequest extends EventEmitter {
    constructor(url, options, callback) {
        super();
        this.url = String(url == null ? '' : url);
        this.options = options || {};
        this.method = String(this.options.method || 'GET').toUpperCase();
        this._callback = callback;
        this._ended = false;
        this.destroyed = false;
    }

    end(body) {
        if (this._ended) return this;
        this._ended = true;
        queueMicrotask(async () => {
            try {
                if (body !== undefined && body !== null &&
                    typeof body !== 'string' && !(body instanceof Uint8Array))
                    throw unsupported('http request body');
                let payload = null;
                if (typeof body === 'string') payload = body;
                else if (body instanceof Uint8Array) {
                    let bin = '';
                    for (let i = 0; i < body.length; i++) bin += String.fromCharCode(body[i]);
                    payload = bin;
                }
                const headers = this.options.headers || {};
                const ctValue = headers['Content-Type'] || headers['content-type'] ||
                                (payload != null ? 'application/json' : null);
                const ct = ctValue != null
                    ? (String(ctValue).includes(':') ? String(ctValue) : 'Content-Type: ' + String(ctValue))
                    : null;
                const result = (this.method === 'GET' || this.method === 'HEAD')
                    ? httpGet(this.url)
                    : httpRequest(this.method, this.url, payload, ct);
                const response = new IncomingMessage(result.status, result.headers, bytesFromHex(result.bodyHex));
                this.emit('response', response);
                if (typeof this._callback === 'function') this._callback(response);
            } catch (error) {
                this.emit('error', error);
            }
        });
        return this;
    }

    destroy(error) {
        if (error) this.emit('error', error);
        this.destroyed = true;
        this.emit('close');
    }
}

export class Server extends EventEmitter {}
export function request(url, options, callback) { return new ClientRequest(url, options, callback); }
export function get(url, options, callback) { const req = request(url, options, callback); req.end(); return req; }
export function createServer() { throw unsupported('http.createServer'); }
export const METHODS = ['GET', 'POST', 'PUT', 'DELETE', 'PATCH', 'HEAD', 'OPTIONS'];
export const STATUS_CODES = { 200: 'OK', 404: 'Not Found', 500: 'Internal Server Error' };
export default { request, get, createServer, IncomingMessage, ClientRequest, Server, METHODS, STATUS_CODES };
